func messageIDHex(id []byte) string { return "0x" + hex.EncodeToString(id) }

func formatTime(t *time.Time) string {
	if t == nil {
		return "—"
	}
	return t.UTC().Format(time.RFC3339)
}

func archiveExpiry(archivedAt *time.Time) string {
	if archivedAt == nil {
		return "—"
	}
	return archivedAt.Add(ArchiveRetention).UTC().Format(time.RFC3339)
}

